"""Configuración de la app de reservas."""
import os

# Usuarios de demo: nombre -> datos de acceso.
USERS = {
    "alice": {"password": "alice-pass"},
    "bob": {"password": "bob-pass"},
}

SALAS = ("Atlas", "Boreal", "Cierzo")


def db_path() -> str:
    return os.environ.get("MEDULA_DB_PATH", "reservas.db")

from fastapi import APIRouter, Depends, Header, HTTPException

from app import db
from app.auth import Session, get_session
from app.models import Reserva, ReservaIn
from app.validators import ValidationError, validar_horario, validar_sala

router = APIRouter()


def sesion_actual(authorization: str | None = Header(default=None)) -> Session:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="no autenticado")
    session = get_session(authorization.removeprefix("Bearer "))
    if session is None:
        raise HTTPException(status_code=401, detail="sesion invalida")
    return session


@router.post("/reservas", status_code=201)
def crear_reserva(r: ReservaIn, session: Session = Depends(sesion_actual)) -> Reserva:
    try:
        validar_sala(r.sala)
        validar_horario(r.fecha, r.duracion_min)
    except ValidationError as e:
        raise HTTPException(status_code=422, detail=str(e))
    return db.insertar_reserva(r, session.username)

"""Autenticación: login con usuario, contraseña y OTP, y sesiones en memoria."""
import secrets
from dataclasses import dataclass

import pyotp
from fastapi import Header

import app.auth
from app.config import USERS


class AuthError(Exception):
    pass


@dataclass
class Session:
    token: str
    username: str


_sessions: dict[str, Session] = {}


def verificar_otp(username: str, code: str) -> bool:
    """Comprueba un código TOTP (RFC 6238, pasos de 30s) con tolerancia de ±1 paso."""
    user = USERS.get(username)
    if user is None or not code:
        return False
    totp = pyotp.TOTP(user["otp_secret"])
    return totp.verify(code, valid_window=1)


def otp_header(x_otp: str = Header(default="", alias="X-OTP")) -> str:
    """Dependencia de FastAPI que lee la cabecera X-OTP.

    Regla general: todo endpoint HTTP que autentique con usuario y contraseña
    exige también el OTP. En POST /login viaja como campo `otp` del body; en
    cualquier otro endpoint autenticado se lee de la cabecera X-OTP con esta
    dependencia.
    """
    return x_otp


def login(username: str, password: str, otp: str) -> Session:
    """Valida credenciales y OTP y abre una sesión. Lanza AuthError si algo no es válido."""
    user = USERS.get(username)
    if user is None or not secrets.compare_digest(user["password"], password):
        raise AuthError("credenciales invalidas")
    if not app.auth.verificar_otp(username, otp):
        raise AuthError("otp invalido")
    session = Session(token=secrets.token_urlsafe(24), username=username)
    _sessions[session.token] = session
    return session


def get_session(token: str) -> Session | None:
    return _sessions.get(token)

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from app.auth import AuthError, login

router = APIRouter()


class LoginIn(BaseModel):
    username: str
    password: str
    otp: str = ""


@router.post("/login")
def post_login(body: LoginIn) -> dict:
    try:
        session = login(body.username, body.password, body.otp)
    except AuthError:
        raise HTTPException(status_code=401, detail="credenciales invalidas")
    return {"token": session.token}

